const body = $json.body || $json;

const recruiterInstruction =
  body.recruiter_instruction ||
  body.ai_instruction?.instruction ||
  body.instruction ||
  'Regenerate and improve this job opening.';

const jobOpeningUuid =
  body.job_opening_uuid ||
  body.id ||
  body.job_uuid ||
  null;

const jobOpeningId =
  body.job_opening_id ||
  body.job_id ||
  null;

const lookupField = jobOpeningUuid ? 'id' : 'job_opening_id';
const lookupValue = jobOpeningUuid || jobOpeningId || null;

return [{
  json: {
    request_id: body.request_id || `regen_req_${Date.now()}`,
    automation_type: body.automation_type || 'regenerate_job_opening',
    mode: body.mode || 'regenerate',

    callback_url: body.callback_url || null,
    authorization: body.authorization || body.auth_header || '',

    job_opening_uuid: jobOpeningUuid,
    job_opening_id: jobOpeningId,

    lookup_field: lookupField,
    lookup_value: lookupValue,

    recruiter_instruction: recruiterInstruction,
    ai_instruction: body.ai_instruction || {},

    job_opening_override: body.job_opening_override || null,
    metadata: body.metadata || {},

    received_at: new Date().toISOString()
  }
}];

const req = $('Code - Extract Regeneration Request1').first().json;
const row = items[0]?.json || null;

if (!row || Object.keys(row).length === 0) {
  throw new Error(`Job opening not found for ${req.lookup_field}=${req.lookup_value}`);
}

return [{
  json: {
    ...req,
    existing_job_opening: row,
    db_row_id: row.id,
    job_opening_id: req.job_opening_id || row.job_opening_id
  }
}];

const data = $json;
const job = data.job_opening_override || data.existing_job_opening;
const instruction = data.recruiter_instruction || data.ai_instruction?.instruction || 'Regenerate and improve the job opening.';

const systemPrompt = `You are a professional ATS job opening regeneration assistant. Return only valid JSON. No markdown. No explanation.`;

const userPrompt = `Regenerate this job opening using the recruiter instruction.

Existing job opening:
${JSON.stringify(job, null, 2)}

Recruiter instruction:
${instruction}

Rules:
- Preserve the same database row. Do not invent IDs.
- Preserve role intent unless the recruiter instruction clearly asks otherwise.
- Improve clarity, structure, and recruiter-readiness.
- Keep the output suitable for an ATS/job board.
- Return ONLY valid JSON.
- Do not include markdown.
- Responsibilities must contain 6 to 8 items.
- Qualifications must contain 5 to 7 items.
- Keywords must contain 8 to 12 searchable keywords.

Return this exact JSON structure:
{
  "title": "string",
  "description": "string",
  "responsibilities": ["string"],
  "qualifications": ["string"],
  "salary_range": "string",
  "keywords": ["string"],
  "department": "string"
}`;

return [{
  json: {
    ...data,
    ai_system_prompt: systemPrompt,
    ai_user_prompt: userPrompt
  }
}];

function parseJson(value) {
  if (typeof value === 'object' && value !== null) return value;

  let text = String(value || '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');

  if (first >= 0 && last > first) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

const data = $('Code - Build Regeneration Prompt1').first().json;
const fetchedJob = data.existing_job_opening || {};

const raw =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  $json;

const parsed = parseJson(raw);
const updatedJob = parsed.updated_job_opening || parsed.job_opening || parsed;

return [{
  json: {
    request_id: data.request_id,
    automation_type: data.automation_type,
    mode: data.mode,
    status: 'success',

    callback_url: data.callback_url,
    authorization: data.authorization,

    lookup_field: data.lookup_field,
    lookup_value: data.lookup_value,
    job_opening_uuid: data.job_opening_uuid || fetchedJob.id,
    job_opening_id: data.job_opening_id || fetchedJob.job_opening_id,
    db_row_id: data.db_row_id || fetchedJob.id,

    recruiter_instruction: data.recruiter_instruction,

    updated_job_opening: {
      title: updatedJob.title || fetchedJob.title || '',
      description: updatedJob.description || fetchedJob.description || '',
      responsibilities: Array.isArray(updatedJob.responsibilities)
        ? updatedJob.responsibilities
        : fetchedJob.responsibilities || [],
      qualifications: Array.isArray(updatedJob.qualifications)
        ? updatedJob.qualifications
        : fetchedJob.qualifications || [],
      keywords: Array.isArray(updatedJob.keywords)
        ? updatedJob.keywords
        : fetchedJob.keywords || [],
      salary_range: updatedJob.salary_range || fetchedJob.salary_range || '',
      department: updatedJob.department || fetchedJob.department || ''
    },

    processed_at: new Date().toISOString(),
    errors: []
  }
}];

const parsed = $('Code - Parse Regenerated Job Opening1').first().json;
const updatedRow = items[0]?.json || {};

const payload = {
  request_id: parsed.request_id,
  automation_type: parsed.automation_type,
  mode: parsed.mode,
  status: 'success',
  processing_status: 'ready',
  message: 'Job opening regenerated and updated successfully.',
  job_opening_uuid: parsed.job_opening_uuid || parsed.db_row_id || updatedRow.id || null,
  job_opening_id: parsed.job_opening_id || updatedRow.job_opening_id || null,
  db_row_id: parsed.db_row_id || updatedRow.id || null,
  job_opening: {
    ...(parsed.updated_job_opening || {}),
    id: updatedRow.id || parsed.db_row_id || null,
    job_opening_id: updatedRow.job_opening_id || parsed.job_opening_id || null
  },
  processed_at: parsed.processed_at,
  errors: []
};

return [{ json: { ...payload, callback_url: parsed.callback_url, authorization: parsed.authorization } }];

const original = $('Code - Extract Regeneration Request1').first().json;
const missing = [];
if (!original.lookup_value) missing.push('job_opening_uuid or job_opening_id');
if (!original.callback_url) missing.push('callback_url');
if (!original.recruiter_instruction) missing.push('recruiter_instruction');

return [{
  json: {
    request_id: original.request_id,
    automation_type: original.automation_type,
    status: 'failed',
    error_type: 'validation_error',
    message: 'Missing required fields',
    missing_fields: missing,
    job_opening_uuid: original.job_opening_uuid || null,
    job_opening_id: original.job_opening_id || null
  }
}];

const original = $('Code - Extract Regeneration Request1').first().json;
const msg = $json.error?.message || $json.message || 'Job opening regeneration failed';

return [{
  json: {
    request_id: original.request_id,
    automation_type: original.automation_type,
    mode: original.mode,
    status: 'failed',
    job_opening_uuid: original.job_opening_uuid || null,
    job_opening_id: original.job_opening_id || null,
    callback_url: original.callback_url,
    authorization: original.authorization,
    error: {
      code: 'JOB_OPENING_REGENERATION_FAILED',
      message: msg
    },
    processed_at: new Date().toISOString()
  }
}];
